142	      nxReleaseConfig: null,
143	    };
144	  }
145	
146	  if (hasInvalidConventionalCommitsConfig(userConfig)) {
147	    return {
148	      error: {
149	        code: 'CONVENTIONAL_COMMITS_SHORTHAND_MIXED_WITH_OVERLAPPING_GENERATOR_OPTIONS',
150	        data: {},
151	      },
152	      nxReleaseConfig: null,
153	    };
154	  }
155	
156	  const gitDefaults = {
157	    commit: false,
158	    commitMessage: 'chore(release): publish {version}',
159	    commitArgs: '',
160	    tag: false,
161	    tagMessage: '',
162	    tagArgs: '',
163	    stageChanges: false,
164	  };
165	  const versionGitDefaults = {
166	    ...gitDefaults,
167	    stageChanges: true,
168	  };
169	  const changelogGitDefaults = {
170	    ...gitDefaults,
171	    commit: true,
172	    tag: true,
173	  };
174	
175	  const defaultFixedReleaseTagPattern = 'v{version}';
176	  /**
177	   * TODO: in v20, make it so that this pattern is used by default when any custom groups are used
178	   */
179	  const defaultFixedGroupReleaseTagPattern = '{releaseGroupName}-v{version}';
180	  const defaultIndependentReleaseTagPattern = '{projectName}@{version}';
181	
182	  const workspaceProjectsRelationship =
183	    userConfig.projectsRelationship || 'fixed';
184	
185	  const defaultGeneratorOptions: {
186	    currentVersionResolver?: string;
187	    specifierSource?: string;
188	  } = {};
189	
190	  if (userConfig.version?.conventionalCommits) {
191	    defaultGeneratorOptions.currentVersionResolver = 'git-tag';
